  "in_reply_to_user_id" : 196226431,
  "text" : "@IAmJeffEmmerson MH diagnosis and treatment w\/drugs is not scientific. I'm not against meds but good med mgmt is needed. A family Dr. should not prescribe &amp; manage MH meds. This means a fundamental change in MH is needed. Anyone notice the shortage of Psychiatric doctors?",
