  "in_reply_to_user_id" : 1262776610,
  "text" : "@IAmJeffEmmerson Mental Health (MH) 2 components; Brain and Mind. Brain is organic, can be studied, results = objective. Mind is subjective. Brain effects Mind, &amp; Mind\/Brain. MH diagnosis is mostly subjective. Mind drugs effect Brain, tolerated by some &amp; not others. Deep subject, point being;..",
